CREATE COLUMN TABLE "TEST_AP"."OSCS" ("statusID" SMALLINT CS_INT NOT NULL , "Name" NVARCHAR(20), "Descriptio" NCLOB MEMORY THRESHOLD 1000, "Locked" NVARCHAR(1), "Active" NVARCHAR(1) DEFAULT 'Y', PRIMARY KEY ("statusID")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "OSCS_NAME" ON "TEST_AP"."OSCS" ( "Name" ASC )